local MedalMaker = {}
local PRODUCTS = {
    pewter_medal = { name = "Pustrasta medalja", tinCost = 1, time = 1, cost = 6, prestige = 1, description = "Pustrasta medalja za majhne zasluge." },
    bronze_medal = { name = "Bronasta medalja", bronzeCost = 1, time = 2, cost = 18, prestige = 2, happiness = 1, description = "Bronasta medalja za vojaške zasluge." },
    silver_medal = { name = "Srebrna medalja", silverCost = 1, time = 3, cost = 55, prestige = 5, happiness = 1, description = "Srebrna medalja za viteške zasluge." },
    gold_medal = { name = "Zlata medalja", goldCost = 1, time = 4, cost = 140, prestige = 10, happiness = 2, description = "Zlata medalja za herojske zasluge." },
    enamelled_medal = { name = "Emajlirana medalja", goldCost = 1, silverCost = 1, glassCost = 1, time = 6, cost = 320, prestige = 18, happiness = 3, description = "Emajlirana medalja z barvnimi polji." },
    royal_order_medal = { name = "Kraljevski redni red", goldCost = 2, silverCost = 2, jewelCost = 2, silkCost = 1, time = 9, cost = 800, prestige = 35, happiness = 7, description = "Kraljevski red z dragulji in svilo za najvišje zasluge." },
}
local BUILDINGS = {
    workshop = { name = "Medaljarska delavnica", cost = { gold = 240, wood = 100 }, upkeep = 6, qualityBonus = 5 },
    forge = { name = "Medaljarska kovačija", cost = { gold = 700, wood = 200, stone = 180, silver = 6 }, upkeep = 17, qualityBonus = 18 },
    enamel_room = { name = "Emajlnica", cost = { gold = 1600, wood = 280, stone = 350, silver = 25, glass = 6 }, upkeep = 38, qualityBonus = 30 },
    royal_medal_atelier = { name = "Kraljevski atelje medalj", cost = { gold = 5800, wood = 500, stone = 700, gold = 50, jewel = 18 }, upkeep = 100, qualityBonus = 55, prestigeBonus = 28 },
}
MedalMaker.tinStock = 12; MedalMaker.bronzeStock = 12; MedalMaker.silverStock = 8; MedalMaker.goldStock = 6; MedalMaker.glassStock = 6; MedalMaker.jewelStock = 6; MedalMaker.silkStock = 6
MedalMaker.productStock = {}; MedalMaker.buildings = {}; MedalMaker.maker = nil; MedalMaker.activeMaking = {}; MedalMaker.totalProducts = 0; MedalMaker.dayTimer = 0
function MedalMaker.init() MedalMaker.tinStock=12; MedalMaker.bronzeStock=12; MedalMaker.silverStock=8; MedalMaker.goldStock=6; MedalMaker.glassStock=6; MedalMaker.jewelStock=6; MedalMaker.silkStock=6; MedalMaker.productStock={}; MedalMaker.buildings={}; MedalMaker.maker=nil; MedalMaker.activeMaking={}; MedalMaker.totalProducts=0; MedalMaker.dayTimer=0; print("[MedalMaker] Royal Medal Maker System initialized (6 products, 4 buildings)") end
function MedalMaker.hireMaker(n,s) s=s or math.random(50,90); local c=440+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MedalMaker.maker={name=n or ("Medaljar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Medaljar najet: %s (spretnost: %d)",MedalMaker.maker.name,s),"success") end; return true end
function MedalMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MedalMaker.build(id) local ok,e=MedalMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MedalMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MedalMaker.getQualityBonus() local b=0; for _,bd in ipairs(MedalMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MedalMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.tinCost and MedalMaker.tinStock<(d.tinCost or 0) then return false,"Premalo kositra" end; if d.bronzeCost and MedalMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.silverCost and MedalMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MedalMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.glassCost and MedalMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.jewelCost and MedalMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.silkCost and MedalMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if #MedalMaker.buildings==0 then return false,"Potrebna delavnica" end; if not MedalMaker.maker then return false,"Potreben medaljar" end; return true end
function MedalMaker.make(pt,qty) qty=qty or 1; local ok,e=MedalMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.tinCost then MedalMaker.tinStock=MedalMaker.tinStock-d.tinCost*qty end; if d.bronzeCost then MedalMaker.bronzeStock=MedalMaker.bronzeStock-d.bronzeCost*qty end; if d.silverCost then MedalMaker.silverStock=MedalMaker.silverStock-d.silverCost*qty end; if d.goldCost then MedalMaker.goldStock=MedalMaker.goldStock-d.goldCost*qty end; if d.glassCost then MedalMaker.glassStock=MedalMaker.glassStock-d.glassCost*qty end; if d.jewelCost then MedalMaker.jewelStock=MedalMaker.jewelStock-d.jewelCost*qty end; if d.silkCost then MedalMaker.silkStock=MedalMaker.silkStock-d.silkCost*qty end; local t=d.time; if MedalMaker.maker then t=math.max(1,t-math.floor(MedalMaker.maker.skill/12)) end; table.insert(MedalMaker.activeMaking,{id="medal_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MedalMaker.completeMaking(m) local q=1.0+(MedalMaker.getQualityBonus()/100); if MedalMaker.maker then q=q+(MedalMaker.maker.skill/180) end; q=math.min(2.0,q); MedalMaker.productStock[m.productType]=(MedalMaker.productStock[m.productType] or 0)+m.quantity; MedalMaker.totalProducts=MedalMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MedalMaker.maker then MedalMaker.maker.itemsMade=MedalMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then MedalMaker.maker.skill=math.min(100,MedalMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Medalja izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"medal.completed",{productName=m.productName,prestige=m.prestige}) end end
function MedalMaker.update(dt) if not _G.state then return end; MedalMaker.dayTimer=MedalMaker.dayTimer+dt; if MedalMaker.dayTimer>=30 then MedalMaker.dayTimer=0; for i=#MedalMaker.activeMaking,1,-1 do local m=MedalMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MedalMaker.completeMaking(m); table.remove(MedalMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MedalMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MedalMaker.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MedalMaker.getStats() return {tinStock=MedalMaker.tinStock,bronzeStock=MedalMaker.bronzeStock,silverStock=MedalMaker.silverStock,goldStock=MedalMaker.goldStock,glassStock=MedalMaker.glassStock,jewelStock=MedalMaker.jewelStock,silkStock=MedalMaker.silkStock,productStock=MedalMaker.productStock,numBuildings=#MedalMaker.buildings,hasMaker=MedalMaker.maker~=nil,makerName=MedalMaker.maker and MedalMaker.maker.name or "—",makerSkill=MedalMaker.maker and MedalMaker.maker.skill or 0,activeMaking=#MedalMaker.activeMaking,totalProducts=MedalMaker.totalProducts} end
return MedalMaker
